// One Slack message summarising this week's hiring per company (free 'company' records).
const rows = $input.all().map(i => i.json).filter(r => r.recordType === 'company' && r.status === 'ok');
rows.sort((a, b) => (b.newJobs || 0) - (a.newJobs || 0));
const lines = rows.map(r => {
  const name = r.companyName || r.companySlug;
  const top = (r.topDepartments || []).slice(0, 3).map(d => d.name || d).join(', ');
  // First run for a company: every open role counts as new (baseline), so report it as a starting point.
  const baseline = r.openJobs > 0 && r.newJobs === r.openJobs && !r.changedJobs && !r.closedJobs;
  const counts = baseline ? `${r.openJobs} open (first week monitored)` :
    `${r.openJobs} open, +${r.newJobs || 0} new, ${r.closedJobs || 0} closed`;
  return `• ${name}: ${counts}` + (top ? ` (top: ${top})` : '');
});
const failed = $input.all().map(i => i.json).filter(r => r.recordType === 'company' && r.status !== 'ok');
if (failed.length) lines.push(`Not read this week: ${failed.map(r => r.companySlug).join(', ')}`);
return [{ json: { text: lines.length ? `Weekly hiring digest\n${lines.join('\n')}` : 'Weekly hiring digest: no data' } }];
